public int score(List<List<String>> batches) {
        int result = 0;
        for (List<String> batch : batches) {
            for (String name : batch) {
                int count = Recipe.portions(name);
                if (count > 0 && count <= 3) {
                    result += count;
                }
            }
        }
        return result;
    }

