public String transition(Status next) {
        if (status != Status.QUEUED) return "unchanged";
        String result = switch (next) {
            case BREWED -> "collected";
            case CANCELLED -> "refunded";
            default -> "unchanged";
        };
        status = next;
        return result;
    }

