public Order place(String customer, Map<String, String> notes,
                       Consumer<Order> onReady, Order.Line... lines) {
        Order order = new Order(customer, List.of(lines), notes);
        orders.add(order);
        if (!fulfill(order).isEmpty()) onReady.accept(order);
        return order;
    }

